<?php if($page==='room'):$room=owned('rooms',intv($_GET['id']??0));$seats=rows('SELECT * FROM room_seats WHERE institution_id=? AND room_id=? ORDER BY row_no,col_no',[inst(),$room['id']]);$locked=(bool)rows('SELECT a.id FROM seating_assignments a JOIN room_seats s ON s.id=a.seat_id WHERE a.institution_id=? AND s.room_id=?',[inst(),$room['id']]);?>
<div class="heading"><div><div class="eyebrow">محرر القاعة</div><h1><?=h($room['code'].' — '.$room['name'])?></h1><p><?=h($room['building'].' / الطابق '.$room['floor_name'])?> · <?=count($seats)?> موقعًا · السعة المسموحة <?=(int)$room['capacity']?></p></div><a class="button secondary" href="?page=rooms">قائمة القاعات</a></div>
<?php if($locked):?><div class="alert">القاعة مرتبطة بخريطة محفوظة، لذلك تعديل المقاعد مقفل لحماية التوزيع. يمكن إنشاء قاعة جديدة إذا تغيّرت الهندسة.</div><?php endif;?>
<section class="card"><h2>المقاعد والممرات</h2><p class="muted">اضغط حالة الموقع للتبديل بين مقعد نشط وممر ومعطّل، ثم احفظ. حدّد مقاعد الوصول الملائمة حسب تجهيزات القاعة الفعلية.</p><div class="editor-hint"><span><i class="pill"></i>نشط</span><span>الممر لا يُعد مقعدًا</span><span>المعطّل مستبعد من التوزيع</span></div>
<form method="post"><?=csrf()?><input type="hidden" name="action" value="seats"><input type="hidden" name="room_id" value="<?=(int)$room['id']?>"><?php if($room['board']==='north'):?><div class="board">السبورة / مقدمة القاعة</div><?php endif;?><div class="room-scroll"><div class="room-layout" style="grid-template-columns:repeat(<?=(int)$room['cols_count']?>,minmax(80px,1fr))"><?php foreach($seats as $s):?><div class="seat <?=h($s['state'])?>"><b><?=h($s['label'])?></b><small>صف <?=(int)$s['row_no']?> · عمود <?=(int)$s['col_no']?></small><input type="hidden" data-seat-state name="seat_state[<?=(int)$s['id']?>]" value="<?=h($s['state'])?>"><button type="button" class="secondary" data-seat-cycle <?=$locked||!can('write')?'disabled':''?>><?=h(['active'=>'مقعد نشط','aisle'=>'ممر','disabled'=>'معطّل'][$s['state']])?></button><label><input type="checkbox" name="accessible[<?=(int)$s['id']?>]" value="1" <?=$s['accessible']?'checked':''?> <?=$locked||!can('write')?'disabled':''?>>وصول ملائم</label></div><?php endforeach;?></div></div><?php if($room['board']==='south'):?><div class="board">السبورة / مقدمة القاعة</div><?php endif;?><p class="muted">المدخل: <?=h($room['entrance']?:'غير محدد')?></p><?php if(can('write')&&!$locked):?><button>حفظ هندسة المقاعد</button><?php endif;?></form></section>
<?php else:$edit=!empty($_GET['edit'])?owned('rooms',(int)$_GET['edit']):null;?>
<div class="heading"><div><div class="eyebrow">هندسة الجلوس</div><h1>القاعات والمقاعد</h1><p>قاعات متاحة واحتياطية، مع فصل السعة الفعلية عن السعة المسموحة.</p></div></div>
<?php if(can('write')):?><section class="card"><h2><?=$edit?'تعديل قاعة غير موزعة':'إضافة قاعة'?></h2><form method="post"><?=csrf()?><input type="hidden" name="action" value="save"><input type="hidden" name="kind" value="room"><input type="hidden" name="id" value="<?=(int)($edit['id']??0)?>"><div class="grid"><?php field('رقم / رمز القاعة','code',$edit['code']??'');field('اسم القاعة','name',$edit['name']??'');field('البناية','building',$edit['building']??'');field('الطابق','floor_name',$edit['floor_name']??'الأرضي');field('عدد الصفوف','rows_count',$edit['rows_count']??5,'number','min="1" max="30"');field('عدد الأعمدة','cols_count',$edit['cols_count']??6,'number','min="1" max="20"');field('السعة المسموحة','capacity',$edit['capacity']??30,'number','min="1" max="600"');field('عدد المراقبين المطلوبين','required_monitors',$edit['required_monitors']??2,'number','min="1" max="10"');selectf('حالة القاعة','status',['available'=>'متاحة','reserve'=>'احتياطية','booked'=>'محجوزة / مستبعدة'],$edit['status']??'available');selectf('السبورة','board',['north'=>'أعلى الخريطة','south'=>'أسفل الخريطة'],$edit['board']??'north');field('موضع المدخل / وصف الوصول','entrance',$edit['entrance']??'','text','',false);?></div><p class="muted">تُنشأ المواقع مرقمة حسب الصف والعمود؛ حرّر الممرات والمقاعد المعطلة بعد الحفظ. تعديل الأبعاد يعيد بناء مقاعد القاعة غير المرتبطة فقط.</p><button>حفظ وفتح محرر المقاعد</button></form></section><?php endif;?>
<section class="card"><h2>القاعات المسجلة</h2><div class="table-wrap"><table><tr><th>القاعة</th><th>الموقع</th><th>الهندسة</th><th>المقاعد النشطة</th><th>السعة الفعلية المسموحة</th><th>المراقبون</th><th>الحالة</th><th>إجراء</th></tr><?php $rooms=rows('SELECT r.*,SUM(s.state=\'active\') AS active_seats FROM rooms r LEFT JOIN room_seats s ON s.room_id=r.id WHERE r.institution_id=? GROUP BY r.id ORDER BY r.code',[inst()]);foreach($rooms as $r):?><tr><td><b><?=h($r['code'])?></b><small><?=h($r['name'])?></small></td><td><?=h($r['building'])?><small><?=h($r['floor_name'])?></small></td><td><?=(int)$r['rows_count']?> × <?=(int)$r['cols_count']?></td><td><?=(int)$r['active_seats']?></td><td><?=min((int)$r['capacity'],(int)$r['active_seats'])?></td><td><?=(int)$r['required_monitors']?></td><td><span class="badge <?=$r['status']==='reserve'?'draft':''?>"><?=h(['available'=>'متاحة','reserve'=>'احتياطية','booked'=>'محجوزة'][$r['status']])?></span></td><td><a href="?page=room&id=<?=(int)$r['id']?>">خريطة المقاعد</a><?php if(can('write')):?> · <a href="?page=rooms&edit=<?=(int)$r['id']?>">تعديل</a><form method="post" class="inline" data-confirm="حذف القاعة ومواقعها غير المرتبطة فقط؟"><?=csrf()?><input type="hidden" name="action" value="delete"><input type="hidden" name="table" value="rooms"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="ghost danger">حذف</button></form><?php endif;?></td></tr><?php endforeach;if(!$rooms):?><tr><td colspan="8" class="empty">لا توجد قاعات بعد.</td></tr><?php endif;?></table></div></section><?php endif;?>
